window.kbPageData["views/entry/k-705cf10485a8579a"] = {"key":"entry/k-705cf10485a8579a","state":{"route":"entry/k-705cf10485a8579a"},"node":{"id":"k-705cf10485a8579a","mode":"k","title":"政务服务错时办理","type":"观点与论证","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["错时服务缓解群众办事时间冲突"],"qs":["国考 2025 行政执法 申论#5"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"错时办理是把部分服务安排在常规工作时间之外，方便工作日难以到场的群众。C市医保局通过双休日轮岗延长了窗口服务时间。","review":{"definition":"错时办理是把部分服务安排在常规工作时间之外，方便工作日难以到场的群众。C市医保局通过双休日轮岗延长了窗口服务时间。","explanation":"申论第5题中，工作日上班时间与窗口服务时间重叠，双休日轮岗让群众可以在休息日到窗口办医保业务。周末不能现场办结的业务，工作人员先收材料、留联系方式，再于工作日电话跟进，减少群众再次到场的需要。这为论证“为群众办好事”提供了服务时间和后续衔接两方面的例证。","references":[],"evidence":"“上班没空办、下班没处办”的痛点、难点问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 申论#5":{"paper":"国考 2025 行政执法 申论","n":5,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3],"card":"e9b26cf35f72426e9b032d20","links":[{"id":"k-705cf10485a8579a","role":"直接考查","why":"材料以医保窗口双休日轮岗说明延长服务时段能缓解群众工作时间与窗口开放时间的冲突。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-705cf10485a8579a":[["国考 2025 行政执法 申论#5"]]}};
